function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var rules=['no silent permission changes','all releases need tests','no data deletion without backup','budgets cannot be exceeded'];var changes=['tune cache size','skip tests for hotfix','raise budget 5 percent','rotate api keys'];var res=changes.map(function(c){var v=rules.filter(function(r){return(c.indexOf('skip tests')>=0&&r.indexOf('tests')>=0)||(c.indexOf('budget')>=0&&r.indexOf('budgets')>=0);});return{change:c,violations:v};});var bad=res.filter(function(x){return x.violations.length;}).length;return{rules:rules,changes:res,passed:changes.length-bad,blocked:bad};}
var SEED = 96501;
console.log(JSON.stringify(demoRun(SEED), null, 1));

